#include <iostream>
#include <string>
#include "../include/indicators.hpp"

int main(int argc, char* argv[]) {
    indicators::CyclicProgress cyclic1(5);
    indicators::CyclicProgress cyclic2(10);
    indicators::CyclicProgress cyclic3(15);

    for (int i = 0; i < 3; ++i) cyclic1.next();
    for (int i = 0; i < 6; ++i) cyclic2.next();
    for (int i = 0; i < 9; ++i) cyclic3.next();

    std::cout << cyclic1.str() << std::endl;
    std::cout << cyclic2.str() << std::endl;
    std::cout << cyclic3.str() << std::endl;

    indicators::ProgressDisplay displays[3];
    displays[0] = indicators::ProgressDisplay(50);
    displays[1] = indicators::ProgressDisplay(100);
    displays[2] = indicators::ProgressDisplay(200);

    displays[0].update(25);
    displays[1].update(75);
    displays[2].update(150);

    for (int i = 0; i < 3; ++i) {
        std::cout << displays[i].display() << std::endl;
    }

    displays[0].increment(5);
    displays[1].increment(10);
    displays[2].increment(20);

    for (int i = 0; i < 3; ++i) {
        std::cout << displays[i].display() << std::endl;
    }

    std::cout << indicators::Format::percentage(0.25f) << std::endl;
    std::cout << indicators::Format::percentage(0.5f, 2) << std::endl;
    std::cout << indicators::Format::percentage(0.75f, 3) << std::endl;
    std::cout << indicators::Format::progress(25, 100) << std::endl;
    std::cout << indicators::Format::progress(50, 100) << std::endl;
    std::cout << indicators::Format::progress(75, 100) << std::endl;
    return 0;
}


